import React, { useEffect, useState } from 'react';
import axios from 'axios';
import KPICard from './KPICard';
import DashboardCharts from './DashboardCharts';
import RecentActivityTable from './RecentActivityTable';

interface Stats {
  total_sent: number;
  open_rate: number;
  unread_rate: number;
  bounce_rate: number;
  click_rate: number;
}

interface ChartData {
  day: string;
  emails: number;
}

const Dashboard: React.FC = () => {
  const [stats, setStats] = useState<Stats | null>(null);
  const [chartData, setChartData] = useState<ChartData[] | null>(null);

  useEffect(() => {
    // Mock data for demo
    setStats({
      total_sent: 1500,
      open_rate: 45.2,
      unread_rate: 54.8,
      bounce_rate: 2.1,
      click_rate: 12.5
    });
    setChartData([
      { day: 'Mon', emails: 200 },
      { day: 'Tue', emails: 300 },
      { day: 'Wed', emails: 250 },
      { day: 'Thu', emails: 400 },
      { day: 'Fri', emails: 350 },
      { day: 'Sat', emails: 150 },
      { day: 'Sun', emails: 100 }
    ]);
    // Uncomment for real API
    // axios.get('/api/dashboard/stats').then(res => setStats(res.data));
    // axios.get('/api/dashboard/email-stats').then(res => setChartData(res.data));
  }, []);

  return (
    <div>
      <KPICard stats={stats} />
      <DashboardCharts data={chartData} />
      <RecentActivityTable />
    </div>
  );
};

export default Dashboard;
